SELECT COUNT(1)
FROM groupon_promotion_item gpi
JOIN groupon_promotion gp ON gpi.groupon_promotion_id = gp.groupon_promotion_id
WHERE gpi.product_id = #{productId}

    AND gp.groupon_promotion_id != #{promotionId}

AND gp.start_time <= #{endTime}
AND gp.end_time >= #{startTime}

select
    gi.*, p.product_name, p.product_sn, p.pic_large, p.pic_thumb, p.pic_url, p.product_price, p.product_brief
from groupon_promotion_item gi
left join product p on gi.product_id = p.product_id


        and gi.groupon_promotion_id = #{pageQuery.grouponPromotionId}


        and p.product_name like concat('%', #{pageQuery.keyword}, '%')


        and p.product_sn like concat('%', #{pageQuery.productSn}, '%')


        and p.brand_id = #{pageQuery.brandId}



